package com.novvy.app.google

import com.novvy.app.BuildConfig

/**
 * ─────────────────────────────────────────────────────────────────────────────
 *  GOOGLE CREDENTIALS LIVE HERE (indirectly).
 *
 *  You do NOT edit this file. You fill in your values in:
 *
 *      android/local.properties
 *
 *  (which is git-ignored and never shipped inside the APK). Example:
 *
 *      GOOGLE_WEB_CLIENT_ID=xxxxxxxx.apps.googleusercontent.com
 *      GOOGLE_API_KEY=AIzaSy...
 *
 *  Those values are surfaced to the app through BuildConfig fields declared in
 *  android/app/build.gradle.kts, and read here.
 *
 *  Steps in Google Cloud Console:
 *   1. Create/select a project.
 *   2. Enable the Gmail API and the Google Drive API.
 *   3. OAuth consent screen -> External (add your test users).
 *   4. Credentials -> Create OAuth client ID -> Android
 *        package name: com.novvy.app
 *        SHA-1: your signing cert (debug keystore is fine for testing)
 *      (For REST access you can also create a "Web application" client and
 *       restrict the API key to Gmail + Drive.)
 *   5. Paste GOOGLE_WEB_CLIENT_ID (and GOOGLE_API_KEY) into local.properties.
 * ─────────────────────────────────────────────────────────────────────────────
 */
object GoogleCredentials {

    /** OAuth 2.0 Web client ID from Google Cloud Console. */
    val webClientId: String
        get() = BuildConfig.GOOGLE_WEB_CLIENT_ID

    /** Optional API key restricted to the Gmail + Drive APIs. */
    val apiKey: String
        get() = BuildConfig.GOOGLE_API_KEY

    val isConfigured: Boolean
        get() = webClientId.isNotBlank() &&
            !webClientId.startsWith("your-") &&
            webClientId.contains("apps.googleusercontent.com")
}